diff --git a/src/pcre2posix.c b/src/pcre2posix.c
index 2f2cdf5..38dc660 100644
--- a/src/pcre2posix.c
+++ b/src/pcre2posix.c
@@ -411,7 +411,7 @@ pcre2_regexec(const regex_t *preg, const char *string, size_t nmatch, regmatch_t
     if (pmatch[0].rm_so < 0 || pmatch[0].rm_eo < 0 || pmatch[0].rm_so > pmatch[0].rm_eo)
       return REG_INVARG;
     so = (PCRE2_SIZE)pmatch[0].rm_so;
-    eo = (PCRE2_SIZE)pmatch[0].rm_eo;
+    eo = (PCRE2_SIZE)(pmatch[0].rm_eo - pmatch[0].rm_so);
   }
   else
   {
@@ -419,7 +419,7 @@ pcre2_regexec(const regex_t *preg, const char *string, size_t nmatch, regmatch_t
     eo = strlen(string);
   }

-  rc = pcre2_match((const pcre2_code *)preg->re_pcre2_code, (PCRE2_SPTR)string + so, (eo - so), 0,
+  rc = pcre2_match((const pcre2_code *)preg->re_pcre2_code, (PCRE2_SPTR)string + so, eo, 0,
                    options, md, NULL);

   /* Successful match */

